def removeStars(s: str) -> str:
    # Initialize an empty stack to simulate the removals
    stack = []
    for c in s:
        if c == '*':
            # Pop the nearest left non-star character
            stack.pop()
        else:
            # Push normal characters, as they might remain
            stack.append(c)
    # Join the stack to get the final string
    return ''.join(stack)
